JS='''
const $$=(q)=>[...document.querySelectorAll(q)];
$$('.print').forEach(b=>b.onclick=()=>window.print());
$$('table').forEach((t,i)=>{const w=document.createElement('div');w.className='table-wrap';const scroll=document.createElement('div');scroll.className='table-scroll';scroll.tabIndex=0;scroll.setAttribute('role','region');scroll.setAttribute('aria-label','Tabela '+(i+1)+'; rolagem horizontal');t.before(w);w.append(scroll);scroll.append(t);const b=document.createElement('button');b.className='copy';b.textContent='Copiar tabela';b.setAttribute('aria-label','Copiar tabela '+(i+1)+' como texto');w.prepend(b);b.onclick=async()=>{const value=[...t.rows].map(r=>[...r.cells].map(c=>c.innerText.replace(/\\s+/g,' ').trim()).join('\\t')).join('\\n');try{await navigator.clipboard.writeText(value)}catch(e){const a=document.createElement('textarea');a.value=value;document.body.append(a);a.select();document.execCommand('copy');a.remove()}b.textContent='Copiada';setTimeout(()=>b.textContent='Copiar tabela',1800)}});
const progress=document.querySelector('.progress');if(progress)addEventListener('scroll',()=>{const d=document.documentElement;progress.style.width=(100*d.scrollTop/Math.max(1,d.scrollHeight-d.clientHeight))+'%'},{passive:true});
const search=document.querySelector('#toc-search');if(search){search.addEventListener('input',()=>{const q=search.value.toLocaleLowerCase('pt-BR');$$('.sidebar a').forEach(a=>a.hidden=!a.textContent.toLocaleLowerCase('pt-BR').includes(q))});addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();search.focus()}})}
if(matchMedia('(max-width:760px)').matches){const d=document.querySelector('.sidebar details');if(d)d.open=false}
const calc=document.querySelector('.calc');if(calc){const ids=['people','capex','bill','avoid','ops','setup','repair'];const usd=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);const update=()=>{let v=Object.fromEntries(ids.map(id=>[id,Math.max(0,Number(document.getElementById(id).value)||0)]));v.people=Math.max(1,Math.floor(v.people));v.avoid=Math.min(100,v.avoid);let old=v.people*v.bill,newCost=old*(1-v.avoid/100)+v.people*(v.ops+v.repair),saving=old-newCost,initial=v.people*v.capex+v.setup;document.querySelector('#saving').textContent=usd(saving);document.querySelector('#payback').textContent=saving>0?(initial/saving).toLocaleString('pt-BR',{maximumFractionDigits:2})+' meses':'Sem retorno';document.querySelector('#year').textContent=usd(saving*12-initial);document.querySelector('#calc-detail').textContent='Investimento: '+usd(initial)+' · Antes: '+usd(old)+'/mês · Depois: '+usd(newCost)+'/mês. Cenário calculado; a parcela evitada deve ser medida na fatura.';};ids.forEach(id=>document.getElementById(id).addEventListener('input',update));update()}
'''
SOURCES={}
def convert(md):
 obj=markdown.Markdown(extensions=['tables','fenced_code','toc','sane_lists'],extension_configs={'toc':{'permalink':False}})
 body=obj.convert(md)
 refs=[];mapping={}
 def link(m):
  url,label=m.group(1),m.group(2)
  if not url.startswith(('https://','http://')):return m.group(0)
  clean=html.unescape(url)
  if clean not in mapping:
   mapping[clean]=len(mapping)+1;refs.append((clean,re.sub('<[^>]+>','',label)))
  n=mapping[clean];SOURCES.setdefault(clean,re.sub('<[^>]+>','',label))
  return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{label}</a><sup class="ref"><a href="#ref-{n}" aria-label="Referência {n}">[{n}]</a></sup>'
 body=re.sub(r'<a href="([^"]+)">(.*?)</a>',link,body,flags=re.S)
 body=re.sub(r'<p><img alt="([^"]*)" src="([^"]*)" ?/?></p>',lambda m:f'<figure class="figure"><a href="{m[2]}" aria-label="Abrir imagem em tamanho original"><img src="{m[2]}" alt="{m[1]}" loading="lazy" decoding="async"></a><figcaption>{m[1]}</figcaption></figure>',body)
 bibliography='<section class="references chapter" id="referencias"><h2>Referências e rastreabilidade</h2><p class="small">Links reunidos desta edição. As ressalvas de acesso, data e força da evidência permanecem junto dos achados. Consultas até 16/10/2026.</p><ol>'
 for i,(u,l) in enumerate(refs,1):bibliography+=f'<li id="ref-{i}"><a href="{html.escape(u)}" target="_blank" rel="noopener noreferrer">{html.escape(l)}</a><span class="url">{html.escape(u)}</span></li>'
 bibliography+='</ol></section>'
 heads=re.findall(r'<h2 id="([^"]+)">(.*?)</h2>',body)
 toc=''.join(f'<a href="#{i}">{t}</a>' for i,t in heads)+'<a href="#referencias">Referências</a>'
 # Wrap h2 chapters, preserving initial prose.
 pieces=re.split(r'(?=<h2 id=)',body)
 body=pieces[0]+''.join('<section class="chapter">'+s+'</section>' for s in pieces[1:])
 return body+bibliography,toc,len(refs)

def calculator():
 return '''<section class="calc no-print-break" aria-labelledby="calc-title"><span class="badge">Cenário ajustável • cálculo local</span><h3 id="calc-title">Quanto precisa sair da fatura para o investimento se pagar?</h3><p class="small">Valores ilustrativos em US$. Nenhum dado digitado é enviado à rede. Operação e reparos são mensais, por pessoa.</p><div class="calc-grid">
<label>Pessoas<input id="people" type="number" min="1" max="10000" value="5"></label><label>Hardware por pessoa · US$<input id="capex" type="number" min="0" value="5000"></label><label>API atual por pessoa/mês · US$<input id="bill" type="number" min="0" value="2000"></label><label>Fatura efetivamente evitada · %<input id="avoid" type="number" min="0" max="100" value="50"></label><label>Operação local por pessoa/mês · US$<input id="ops" type="number" min="0" value="100"></label><label>Implantação + contingência · US$<input id="setup" type="number" min="0" value="16400"></label><label>Reparo/trabalho extra por pessoa/mês · US$<input id="repair" type="number" min="0" value="0"></label></div><div class="results" aria-live="polite"><div><small>Economia mensal líquida</small><strong id="saving">US$ 4.500</strong></div><div><small>Retorno simples</small><strong id="payback">9,2 meses</strong></div><div><small>Saldo no primeiro ano</small><strong id="year">US$ 12.600</strong></div></div><p id="calc-detail" class="small" style="margin-top:18px"></p></section>'''

def topbar(active):
 return '<div class="progress"></div><a class="skip" href="#conteudo">Pular para o conteúdo</a><header class="topbar"><a class="brand" href="relatorio.html">ENGENHARIA · IA SOB CONTROLE</a><nav aria-label="Documentos">'+''.join(f'<a href="{f}"'+(' aria-current="page"' if f==active else '')+f'>{l}</a>' for f,l in [('relatorio.html','Pesquisa'),('proposta.html','Investimento'),('slides.html','Diretoria')])+'</nav><button class="print">Imprimir / PDF</button></header>'

def document(file,title,subtitle,eyebrow,md,calc=False):
 body,toc,count=convert(md)
 if calc:body=calculator()+body
 out=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{html.escape(subtitle)}"><title>{html.escape(title)}</title><style>{CSS}</style></head><body>{topbar(file)}<div class="hero"><div class="eyebrow">{eyebrow}</div><h1>{title}</h1><p class="dek">{subtitle}</p><div class="meta">Edição de 16 outubro 2026 · {count} referências vinculadas · HTML estático, sem serviços externos</div></div><div class="layout"><aside class="sidebar"><details open><summary>Neste documento</summary><label class="visually-hidden" for="toc-search">Buscar seção no índice</label><input id="toc-search" type="search" placeholder="Filtrar índice · Ctrl K">{toc}</details></aside><main id="conteudo">{body}</main></div><footer class="foot">Pesquisa cumulativa para decisão empresarial. Nenhum benchmark de modelo foi executado por esta pesquisa. Fontes, hipóteses e limitações estão identificadas. Abra os três HTMLs diretamente no navegador; mantenha a pasta assets ao lado.</footer><script>{JS}</script></body></html>'''
 (ROOT/file).write_text(out)
 return count

md=((BASE/'RELATORIO_PESQUISA_MODELOS_LOCAIS.md') if (BASE/'RELATORIO_PESQUISA_MODELOS_LOCAIS.md').exists() else (ROOT/'RELATORIO_PESQUISA_MODELOS_LOCAIS.md')).read_text().replace('pesquisa_html/assets/','assets/').replace('pesquisa_html/dados/','dados/')
md=re.sub(r'^# .*\n','',md,count=1)
# Collapse literal conversational requests without removing any research content.
md=re.sub(r'(### (?:Pedido original desta atualização — preservado literalmente|Solicitação recebida — registro literal)\n)(.*?)(?=\n### )',lambda m:'<details class="archive"><summary>'+m[1].strip('# \n')+'</summary>\n\n'+m[2]+'\n</details>\n',md,flags=re.S)
needle='Como antecedente de código, [Textbooks Are All You Need'
md=md.replace(needle,'![Tabela original FigmaTrace: precisão por avaliação e método de preparação dos dados](assets/figmatrace-tabela.webp)\n\nFonte visual: [FigmaTrace, tabela 3](https://arxiv.org/html/2608.21460v1), captura do HTML original; inclui regressões e a linha de média para permitir conferência.\n\n'+needle)
lead='''## Orientação para leitura e decisão

Este dossiê reúne a pesquisa acumulada, com benchmarks, custos, casos empresariais e controles de segurança. A hipótese empresarial é testar inferência local para o trabalho verificável e conservar a nuvem para tarefas autorizadas em que ela entregue mais valor. A decisão deve acompanhar qualidade, custo por tarefa e dados que deixam o ambiente.

O material tem três níveis de leitura: este relatório preserva o detalhe e as fontes; a [proposta de investimento](proposta.html) organiza problema, solução e orçamento; os [slides para diretoria](slides.html) destacam a decisão e os limites. Tabelas HTML podem ser copiadas. As imagens de fontes são acompanhadas de origem e foram conferidas visualmente.

**Atualizações desta edição:** relatos de regressão do Opus 4.8 foram ampliados com dados públicos; as duas transcrições foram verificadas por alegação; Google, NVIDIA e runtimes locais oferecem exemplos de controles aplicáveis. A ausência de prova de uma intenção empresarial não elimina a experiência relatada pelos programadores. Segurança local é administrável, mas precisa abranger ferramentas, rede, logs e acesso físico.

'''
count=document('relatorio.html','Modelos locais para engenharia de software','Evidências, desempenho, economia e segurança — do computador do desenvolvedor à infraestrutura compartilhada.','01 / Relatório de pesquisa',lead+md)
proposal=(ROOT/'PROPOSTA_INVESTIMENTO.md').read_text();proposal=re.sub(r'^# .*\n','',proposal,count=1)
document('proposta.html','Investir em capacidade local de IA','Problema, solução e investimento necessário para um piloto de engenharia com controle de custos e dados.','02 / Proposta de investimento',proposal,True)

