DECKJS='''
const slides=[...document.querySelectorAll('.slide')];let index=0;const counter=document.querySelector('.slide-count');const show=(i)=>{index=Math.max(0,Math.min(slides.length-1,i));slides[index].scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});history.replaceState(null,'','#slide-'+(index+1));};document.querySelector('#previous').onclick=()=>show(index-1);document.querySelector('#next').onclick=()=>show(index+1);document.querySelector('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.()};new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){index=slides.indexOf(e.target);counter.textContent=(index+1)+' / '+slides.length;}})},{threshold:.55}).observe(slides[0]);const io=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){index=slides.indexOf(e.target);counter.textContent=(index+1)+' / '+slides.length;}})},{threshold:.55});slides.forEach(s=>io.observe(s));addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(index+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(index-1)}if(e.key==='Home'){e.preventDefault();show(0)}if(e.key==='End'){e.preventDefault();show(slides.length-1)}});
'''
deckbody=''.join(f'<section class="slide {"dark" if dark else ""}" id="slide-{i}" aria-label="Slide {i}: {html.escape(title)}"><div class="eyebrow">{k}</div><h2>{title}</h2><div class="slide-content">{body}</div><div class="source">{source}</div><span class="slide-number">{i:02} / {len(slides):02}</span></section>' for i,(k,title,body,source,dark) in enumerate(slides,1))
